{
  "name": "@k98kurz/opencode-fixtodo",
  "version": "0.0.3",
  "description": "OpenCode v1 plugin that restores the todoread tool and appends the current todo list to compaction summaries",
  "type": "module",
  "license": "ISC",
  "exports": "./fixtodo.ts",
  "main": "./fixtodo.ts",
  "publishConfig": {
    "access": "public"
  },
  "files": [
    "fixtodo.ts",
    "readme.md",
    "license"
  ],
  "sideEffects": false,
  "keywords": [
    "opencode",
    "opencode-plugin",
    "todo"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/k98kurz/opencode-fixtodo.git"
  },
  "homepage": "https://pycelium.com/",
  "bugs": {
    "url": "https://github.com/k98kurz/opencode-fixtodo/issues"
  },
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "node --test",
    "publish:npm": "npm publish",
    "publish:github": "npm publish --registry https://npm.pkg.github.com",
    "prepublishOnly": "npm run typecheck && npm test"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.18.35"
  },
  "devDependencies": {
    "@opencode-ai/sdk": "^1.18.35",
    "typescript": "5.8.2"
  }
}
